-- Preserve applied migration history. Starter translations must not claim review of earlier custom English copy.
-- Data-only correction: owner-written/approved Spanish and every English field remain untouched.
INSERT INTO translation_versions(id,entity_type,entity_id,locale,value,source_revision,approved,actor)
 SELECT lower(hex(randomblob(16))),entity_type,entity_id,locale,value,source_revision,approved,'system:starter-review' FROM content_translations WHERE entity_type='site' AND entity_id='site' AND actor='system:starter-copy' AND approved=0 AND source_revision>0 AND EXISTS(SELECT 1 FROM settings s WHERE s.key='site' AND (json_extract(s.value,'$.intro') IS NOT 'Hands-on arts and crafts for curious kids. Make something special, explore something new, and let creativity lead the way.' OR json_extract(s.value,'$.promotion') IS NOT 'Make room for a little creativity.' OR json(json_extract(s.value,'$.faqs')) IS NOT '[{"question":"What ages are the workshops for?","answer":"Check each workshop for its recommended age range."},{"question":"How do I register?","answer":"Choose a workshop and an available date. A parent or guardian completes the registration and secure checkout."}]'));
UPDATE content_translations SET source_revision=0,revision=revision+1,actor='system:starter-review',updated_at=unixepoch() WHERE entity_type='site' AND entity_id='site' AND actor='system:starter-copy' AND approved=0 AND source_revision>0 AND EXISTS(SELECT 1 FROM settings s WHERE s.key='site' AND (json_extract(s.value,'$.intro') IS NOT 'Hands-on arts and crafts for curious kids. Make something special, explore something new, and let creativity lead the way.' OR json_extract(s.value,'$.promotion') IS NOT 'Make room for a little creativity.' OR json(json_extract(s.value,'$.faqs')) IS NOT '[{"question":"What ages are the workshops for?","answer":"Check each workshop for its recommended age range."},{"question":"How do I register?","answer":"Choose a workshop and an available date. A parent or guardian completes the registration and secure checkout."}]'));
